import {escapeHtml as h,number} from './domain.js';
import {badge} from './art.js';
const branches={infrastructure:['Navigation & énergie','⌁'],intelligence:['Renseignement','◈'],exploitation:['Exploitation','▥'],warfare:['Art de la guerre','✦'],scanning:['Reconnaissance','◎']};
const duration=n=>Number(n)>=24?`${Math.floor(n/24)} j${n%24?` ${n%24} h`:''}`:`${n} h`;
const date=v=>new Date(v).toLocaleString('fr-FR',{dateStyle:'short',timeStyle:'short'});
const errorBox='<p class="form-error" role="alert" hidden></p>';
export function researchTreeView(data,treasury,selectedId){
 const catalog=data.catalog||[],jobs=data.research_jobs||[],worlds=data.planets||[],selected=worlds.find(p=>p.id===selectedId)||worlds[0],busy=new Set(jobs.map(j=>j.planet_id));
 const card=c=>{const job=jobs.find(j=>j.key===c.key),maxed=c.level>=c.max_level,lab=c.eligible_planets.find(p=>p.id===selected?.id),canStart=!maxed&&!job&&c.prerequisites_met&&lab&&!lab.busy&&treasury>=c.next_cost;
 return `<article id="research-${h(c.key)}" class="research-node ${h(c.branch)} ${maxed?'researched':job?'researching':canStart?'available':'locked'}"><header><span class="research-glyph" aria-hidden="true">${branches[c.branch]?.[1]||'◇'}</span><div><h3>${h(c.name)}</h3><small>${job?'Recherche en cours':c.level?`Niveau ${c.level} acquis`:'Non recherchée'}${c.max_level>1&&!maxed?` · prochain ${c.level+1}`:''}</small></div>${c.race?badge('race',c.race):c.resource?badge('resource',c.resource):''}</header><p>${h(c.effect)}</p>${c.requires.length?`<div class="research-prerequisites">${c.requires.map(r=>{const parent=catalog.find(x=>x.key===r.key);return `<button class="${parent?.level>=r.level?'met':''}" data-research-jump="${h(r.key)}" title="Prérequis">↳ ${h(parent?.name||r.key)}${r.level>1?' '+r.level:''}</button>`;}).join('')}</div>`:''}${maxed?'<strong class="research-owned">Acquise</strong>':job?`<span class="research-finish">${h(job.planet)} · ${date(job.finishes_at)}</span>`:`<form data-technology="research"><input type="hidden" name="technology" value="${h(c.key)}"><input type="hidden" name="planet_id" value="${h(selected?.id||'')}"><input type="hidden" name="expected_level" value="${c.level+1}"><div class="research-price"><b>${number(c.next_cost)} Þ</b><small>${duration(c.next_hours)}</small></div><button class="secondary" type="submit" ${canStart?'':'disabled'}>${!c.prerequisites_met?'Prérequis':!lab?'Laboratoire incompatible':lab.busy?'Laboratoire occupé':treasury<c.next_cost?'Fonds insuffisants':'Rechercher →'}</button>${errorBox}</form>`}</article>`;};
 return `<section class="research-tree"><div class="research-toolbar"><label>Laboratoire<select id="research-planet">${worlds.map(p=>`<option value="${h(p.id)}" ${selected?.id===p.id?'selected':''}>${h(p.name)}${busy.has(p.id)?' · occupé':''}</option>`).join('')}</select></label><div class="research-lab-traits">${selected?badge('race',selected.race)+badge('resource',selected.resource):''}<span>${Math.max(0,worlds.length-busy.size)} laboratoire(s) libre(s)</span></div><span>${catalog.filter(c=>c.level>0).length} technologies acquises</span></div>${jobs.length?`<div class="research-active">${jobs.map(j=>{const progress=Math.max(0,Math.min(100,(Date.now()-new Date(j.started_at))/(new Date(j.finishes_at)-new Date(j.started_at))*100));return `<article><div><strong>${h(j.name)}${j.level>1?' '+j.level:''}</strong><small>${h(j.planet)} · fin ${date(j.finishes_at)}</small></div><progress value="${progress}" max="100" aria-label="Progression de la recherche"></progress><form data-technology="research_cancel"><input type="hidden" name="job_id" value="${h(j.id)}"><button class="text-button" type="submit">Annuler</button>${errorBox}</form></article>`;}).join('')}</div>`:''}<nav class="research-filters" aria-label="Branches technologiques"><button data-research-filter="all" aria-pressed="true">Tout</button>${Object.entries(branches).map(([key,[label,glyph]])=>`<button data-research-filter="${key}" aria-pressed="false">${glyph} ${label}</button>`).join('')}</nav>${Object.entries(branches).map(([key,[title,glyph]])=>`<section class="research-branch ${key}" data-research-branch="${key}"><h2><span aria-hidden="true">${glyph}</span>${title}</h2><div class="research-nodes">${catalog.filter(c=>c.branch===key).map(card).join('')}</div></section>`).join('')}</section>`;
}
export function bindResearchTree(state,render){
 document.querySelector('#research-planet')?.addEventListener('change',event=>{state.researchPlanet=event.target.value;render();});
 document.querySelectorAll('[data-research-filter]').forEach(button=>button.onclick=()=>{document.querySelectorAll('[data-research-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.querySelectorAll('[data-research-branch]').forEach(section=>section.hidden=button.dataset.researchFilter!=='all'&&section.dataset.researchBranch!==button.dataset.researchFilter);});
 document.querySelectorAll('[data-research-jump]').forEach(button=>button.onclick=()=>{const target=document.getElementById('research-'+button.dataset.researchJump);if(!target)return;target.closest('[data-research-branch]').hidden=false;target.scrollIntoView({behavior:'smooth',block:'center'});});
}
export const technologyHelp=`<h3>Recherche technologique</h3><p>Une seule recherche peut occuper une planète, mais plusieurs de vos planètes peuvent travailler en parallèle. Le coût est payé au lancement. La découverte est acquise au joueur ; perdre le laboratoire n’efface pas les technologies terminées. Une recherche inachevée est annulée et remboursée si le laboratoire est conquis. Une annulation volontaire rembourse également son coût. Les prérequis, races et ressources du laboratoire sont contrôlés par le serveur. Les branches répétables ne cumulent pas plusieurs réductions identiques.</p><h3>Énergie, téléportation et navigation</h3><p>La recharge coûte 150 000 Þ et nécessite 12 h de recherche. Elle fournit 10 charges sur chaque planète et recharge une charge par heure. Les quatre niveaux de Magmas énergétiques autorisent des réserves de 25, 50, 75 puis 100 charges ; chaque place doit ensuite être achetée localement. La première place supplémentaire coûte 5 000 Þ, puis le prix augmente de 5,5 % par rang. Les réserves achetées avant l’arbre technologique sont conservées.</p><p>La téléportation coûte 300 000 Þ et 24 h de recherche. Elle transfère seulement les soldats au sol entre deux propriétaires ayant cette technologie, avec au moins une extrémité vous appartenant. La capacité de base est un soldat par énergie, doublée entre vos propres mondes. Les trois améliorations portent cette capacité à 2, 3 puis 5 soldats, toujours doublée entre vos mondes. Les joueurs qui avaient déjà la TP disposent de l’amélioration III. Le clan commun, le code d’accès ou une infiltration à 90 % donnent accès à un monde étranger ; l’infiltration ne révèle jamais le code. Après conquête, le raccordement demande 2 h par planète déjà contrôlée. Les soldats téléportés sont N/A 1.</p><p>Voyage amélioré multiplie chaque nouveau trajet par 0,85 à chaque niveau, jusqu’à trois niveaux. Les voyages déjà partis conservent leur durée ; un changement de destination recalcule le trajet depuis la position atteinte. Une porte stellaire relie un réseau protégé par code. La connexion initiale demande 24 h, plus 6 h par porte déjà reliée ou en connexion. Le saut prend 10 h et conserve le délai N/A 1 à l’arrivée. Une porte coûte une énergie par heure. Si la destination est déconnectée, les flottes en saut sont dispersées vers des mondes encore présents.</p><h3>Infiltration et contre-infiltration</h3><p>Une infiltration exige une liaison active entre origine et cible, la création initiale du monde cible, ou au moins deux jours de contrôle dans les 200 derniers jours. Elle progresse de cinq points par jour jusqu’à votre objectif. Avant 30 %, une infiltration fondée uniquement sur le commerce disparaît si sa liaison est rompue. Il n’existe aucun bonus racial intrinsèque à l’infiltration. Certaines recherches spécialisées restent réservées à une race.</p><p>Les seuils révèlent : 10 % population et investissements de civilisation ; 20 % capacités, liaisons et état de la planète ; 30 % propriétaire et clan ; 40 % énergie ; 50 % forces ; 70 % infiltrations ; 90 % accès TP et captivité. À 100 %, la planète passe sous contrôle anonyme pendant 21 jours, conserve ses fortifications et son régime, et ses armées au sol sont intégrées. Un protectorat devient Conseil. Le plafond de douze mondes reste applicable. L’identité d’un propriétaire anonyme reste masquée, y compris dans l’annuaire du clan.</p><p>L’entretien d’une infiltration en progression est de 1 000 Þ/jour par niveau de civilisation cible, avant réductions technologiques. Il diminue de 90 % une fois l’objectif atteint. Tout bloquer gèle les infiltrations et interdit les nouvelles, pour 2 000 Þ/jour par niveau de civilisation. Détecter et nettoyer effectue un contrôle quotidien : à 50 %, chaque infiltration a une chance sur deux d’être éliminée ; coût de 500 Þ/jour par niveau de civilisation à cette précision. La précision peut atteindre 100 %. Les réductions technologiques s’appliquent au coût. Une infiltration ayant atteint 100 % ne peut être nettoyée que par purification.</p><p>À 90 %, le drainage détourne une part des revenus civils et commerciaux, avec un plafond partagé de 35 % sur un monde joueur, 70 % sur un neutre. Le taux ne change qu’une fois par 24 h. Au plafond, les pertes supplémentaires représentent 0,5 % de population par jour et un niveau de civilisation par 30 jours, sans descendre sous civ 1 ; elles diminuent proportionnellement au drainage. Le risque de détection augmente avec le drainage. La purification nécessite la Tyrannie : elle détruit immédiatement vos infiltrations sortantes, bloque le commerce et gèle les infiltrations entrantes pendant sept jours, puis les élimine. Interrompre la purification ne restaure pas vos infiltrations perdues.</p><h3>Technologies militaires</h3><p>Les niveaux de vaisseaux et d’armées ne s’appliquent qu’aux nouvelles unités. Les regroupements et transports conservent une moyenne pondérée. Le camp ayant le niveau moyen le plus élevé obtient 3 % de puissance par niveau d’écart, plafonné à 30 %. Le camouflage masque le propriétaire, réduit la puissance de 25 % et impose N/A 1 lorsqu’il est changé, sans prolonger une indisponibilité déjà en cours. Une capture camouflée accorde 21 jours de contrôle anonyme.</p><p>Le bombardement massif frappe population, capacités et usines sous maîtrise spatiale ; les bombardiers deviennent deux fois plus vulnérables au feu spatial. Valeurs alpha : 50 habitants, 0,02 capacité et 0,01 usine par bombardier et par heure, avec fractions conservées. Les tranchées stellaires ralentissent les dégâts et la production de vaisseaux d’un facteur trois. Leur activation coûte deux énergies, leur entretien une énergie par heure, plus une en cas de supériorité ennemie pendant un combat. Elles ne peuvent être levées dans les 24 h suivant une conquête, ni si la puissance spatiale ennemie sur place dépasse la défense d’au moins 1 %.</p><h3>Scans et armes planétaires</h3><p>Un scan coûte 80 000 Þ, prend quatre heures et vise l’une des trente planètes les plus proches. Mode normal : une énergie, origine annoncée ; anonyme : deux énergies, cible avertie sans origine ; furtif : quatre énergies, cible non avertie. Les deux modes discrets ont chacun 5 % de risque de se dégrader d’un cran. Les scans de forces estiment leur puissance à ±10 %. Le scan commercial montre les cinq liaisons les plus importantes.</p><p>Les quatre recherches de confinement coûtent au total 20 millions Þ. Un trou noir exige la Tyrannie, 48 h de préparation et une énergie d’entretien par heure. Son activation détruit irréversiblement la planète, ses installations, les forces stationnées et les flottes parties depuis moins de deux heures, sauf par porte stellaire. Les futures arrivées sont absorbées. Le confinement offensif demande une recherche supplémentaire et 96 h de préparation publique ; il condamne un huitième des mondes les plus proches, absorbés en 16 à 31 jours selon la distance. Une onde énergétique vide les réserves à portée et réduit les fortifications à 13 % au maximum ; celles-ci peuvent ensuite se reconstruire. Une charge couvre 11,25 unités de distance. Les trous noirs prêts sont annulés par l’onde ; ceux encore en préparation ne le sont pas directement.</p><h3>Démographie</h3><p>Croissance de base : 0,5 % par jour, multipliée par 1 + 0,02 × (civilisation − 1). Conseil +20 %, Tyrannie −20 % ; commerce actif jusqu’à +25 %. Un combat sur l’un des cinq mondes les plus proches divise la croissance par deux ; une guerre sur le monde l’arrête. Les neutres ne croissent jamais. Le temps hors connexion et les fractions sont conservés.</p>`;
